INSERT INTO news (id, slug, title, subtitle, summary, body, body_text, category_id, city_id, neighborhood_id, image_id, video, status, origin, is_urgent, is_sponsored, sponsor_name, sponsor_url, seo_title, seo_description, reading_time_minutes, featured_rank, published_at, updated_at) VALUES ('0192a1b2-000a-7000-8000-000000000005', 'temporal-alaga-ruas-de-copacabana-e-botafogo', 'Temporal alaga ruas de Copacabana e Botafogo; Defesa Civil emite alerta', 'Sirenes foram acionadas em áreas de risco e motoristas devem evitar a orla até a noite', 'Chuva forte no início da tarde deixou pontos de alagamento na Avenida Atlântica e na Rua São Clemente.', '[{"type":"paragraph","html":"Uma chuva forte que começou por volta das 14h desta quarta-feira provocou alagamentos em vários pontos de <strong>Copacabana</strong> e <strong>Botafogo</strong>. A Defesa Civil municipal elevou o alerta e acionou as sirenes em comunidades próximas."},{"type":"quote","text":"A previsão indica chuva moderada a forte até a madrugada. Pedimos atenção redobrada.","source":"Defesa Civil do Rio"},{"type":"paragraph","html":"Na Avenida Atlântica, a água chegou à altura do meio-fio nas proximidades do Posto 4. Em Botafogo, a Rua São Clemente teve trânsito lento por mais de uma hora."},{"type":"paragraph","html":"A orientação é que moradores evitem deslocamentos desnecessários e não atravessem áreas alagadas. Em emergências, o telefone da Defesa Civil é o 199."}]'::jsonb, 'Uma chuva forte que começou por volta das 14h desta quarta-feira provocou alagamentos em vários pontos de Copacabana e Botafogo. A Defesa Civil municipal elevou o alerta e acionou as sirenes em comunidades próximas.
