INSERT INTO news (id, slug, title, subtitle, summary, body, body_text, category_id, city_id, neighborhood_id, image_id, video, status, origin, is_urgent, is_sponsored, sponsor_name, sponsor_url, seo_title, seo_description, reading_time_minutes, featured_rank, published_at, updated_at) VALUES ('0192a1b2-000a-7000-8000-000000000006', 'tunel-reboucas-tem-faixa-fechada-apos-acidente', 'Túnel Rebouças tem faixa fechada após acidente no sentido Lagoa', NULL, 'Colisão entre dois carros e uma moto deixou uma pessoa ferida; trânsito chega ao Rio Comprido.', '[{"type":"paragraph","html":"Um acidente envolvendo dois carros e uma motocicleta fechou a faixa da esquerda do Túnel Rebouças, no sentido Lagoa, no início da tarde."},{"type":"paragraph","html":"O motociclista foi atendido pelo Corpo de Bombeiros e levado consciente para o Hospital Miguel Couto. A CET-Rio orienta o uso da Rua Jardim Botânico como alternativa."}]'::jsonb, 'Um acidente envolvendo dois carros e uma motocicleta fechou a faixa da esquerda do Túnel Rebouças, no sentido Lagoa, no início da tarde.
