INSERT INTO news (id, slug, title, subtitle, summary, body, body_text, category_id, city_id, neighborhood_id, image_id, video, status, origin, is_urgent, is_sponsored, sponsor_name, sponsor_url, seo_title, seo_description, reading_time_minutes, featured_rank, published_at, updated_at) VALUES ('0192a1b2-000a-7000-8000-000000000007', 'falta-de-luz-atinge-parte-do-leblon', 'Falta de luz atinge parte do Leblon; concessionária promete religar até 18h', NULL, 'Cerca de 3 mil imóveis estão sem energia desde o fim da manhã por causa de um defeito em cabo subterrâneo.', '[{"type":"paragraph","html":"Moradores de ruas próximas à Avenida Ataulfo de Paiva estão sem luz desde as 11h. Semáforos apagados complicam o trânsito na região."},{"type":"paragraph","html":"A concessionária informou que equipes trabalham na troca de um trecho de cabo subterrâneo e que o fornecimento deve ser restabelecido até as 18h."}]'::jsonb, 'Moradores de ruas próximas à Avenida Ataulfo de Paiva estão sem luz desde as 11h. Semáforos apagados complicam o trânsito na região.
