INSERT INTO news (id, slug, title, subtitle, summary, body, body_text, category_id, city_id, neighborhood_id, image_id, video, status, origin, is_urgent, is_sponsored, sponsor_name, sponsor_url, seo_title, seo_description, reading_time_minutes, featured_rank, published_at, updated_at) VALUES ('0192a1b2-000a-7000-8000-000000000008', 'policia-prende-suspeito-de-assaltos-na-orla-de-copacabana', 'Polícia prende suspeito de assaltos em série na orla de Copacabana', NULL, 'Homem de 24 anos foi identificado por câmeras e reconhecido por pelo menos cinco vítimas.', '[{"type":"paragraph","html":"Policiais militares prenderam na manhã desta quarta-feira um homem suspeito de praticar ao menos cinco roubos na orla de Copacabana nas últimas duas semanas."},{"type":"paragraph","html":"Segundo a PM, o suspeito abordava pedestres no calçadão no início da manhã e fugia de bicicleta. Ele foi levado para a 12ª DP."}]'::jsonb, 'Policiais militares prenderam na manhã desta quarta-feira um homem suspeito de praticar ao menos cinco roubos na orla de Copacabana nas últimas duas semanas.
