INSERT INTO news (id, slug, title, subtitle, summary, body, body_text, category_id, city_id, neighborhood_id, image_id, video, status, origin, is_urgent, is_sponsored, sponsor_name, sponsor_url, seo_title, seo_description, reading_time_minutes, featured_rank, published_at, updated_at) VALUES ('0192a1b2-000a-7000-8000-000000000009', 'ciclista-e-assaltado-na-orla-de-ipanema', 'Ciclista é assaltado na orla de Ipanema; PM reforça patrulhamento', NULL, 'Vídeo enviado por leitor mostra a abordagem na altura do Posto 9, no começo da manhã.', '[{"type":"paragraph","html":"Um ciclista foi rendido por dois homens na ciclovia da orla de Ipanema, perto do Posto 9, por volta das 6h. Os criminosos levaram a bicicleta e o celular da vítima."},{"type":"paragraph","html":"A Polícia Militar informou que vai reforçar o patrulhamento na orla nas primeiras horas do dia. O caso foi registrado na 14ª DP."}]'::jsonb, 'Um ciclista foi rendido por dois homens na ciclovia da orla de Ipanema, perto do Posto 9, por volta das 6h. Os criminosos levaram a bicicleta e o celular da vítima.
