INSERT INTO news (id, slug, title, subtitle, summary, body, body_text, category_id, city_id, neighborhood_id, image_id, video, status, origin, is_urgent, is_sponsored, sponsor_name, sponsor_url, seo_title, seo_description, reading_time_minutes, featured_rank, published_at, updated_at) VALUES ('0192a1b2-000a-7000-8000-00000000000a', 'camara-aprova-ampliacao-de-ciclovias-na-zona-sul', 'Câmara aprova projeto que amplia ciclovias na Zona Sul', 'Plano prevê 18 km de novas faixas ligando Botafogo, Humaitá e Jardim Botânico', 'Texto segue para sanção do prefeito e prevê obras a partir do primeiro semestre de 2027.', '[{"type":"paragraph","html":"A Câmara Municipal aprovou em segunda votação o projeto que cria 18 quilômetros de novas ciclovias na Zona Sul, com ligação entre Botafogo, Humaitá e Jardim Botânico."},{"type":"paragraph","html":"O texto segue para sanção. A previsão da Secretaria de Transportes é iniciar as obras no primeiro semestre de 2027."},{"type":"paragraph","html":"Associações de moradores pedem que o traçado seja apresentado em audiência pública antes do início das intervenções."}]'::jsonb, 'A Câmara Municipal aprovou em segunda votação o projeto que cria 18 quilômetros de novas ciclovias na Zona Sul, com ligação entre Botafogo, Humaitá e Jardim Botânico.
